    var b=new TeachingTip{IsLightDismissEnabled=variant=="Transient",Title="Explore this feature",Subtitle=variant=="TitleOnly"?"":"Helpful information appears next to the target.",Target=variant=="Untargeted"?null:target,PreferredPlacement=TeachingTipPlacementMode.Top,ActionButtonContent=variant=="TitleOnly"?null:"Learn more",CloseButtonContent=variant=="TitleOnly"?null:"Got it",TailVisibility=variant=="TailCollapsed"?TeachingTipTailVisibility.Collapsed:TeachingTipTailVisibility.Auto};
    if(variant=="Hero")b.HeroContent=new Border{Height=80,Background=Brush(0,120,212)};root.Children.Add(b);b.IsOpen=true;
    await Record("TeachingTip-"+variant,"TeachingTip",new{title=b.Title,subtitle=b.Subtitle,preferredPlacement="Top",actionButtonContent=variant=="TitleOnly"?"":"Learn more",closeButtonText=variant=="TitleOnly"?"":"Got it",tailVisibility=b.TailVisibility.ToString(),isLightDismissEnabled=b.IsLightDismissEnabled},b);b.IsOpen=false;await Task.Delay(200);
   }
   async Task Motion(string label,string kind,FrameworkElement control,Action show,Action hide,object props){
    root.UpdateLayout();await Task.Delay(100);
    async Task Capture(string phase,int requested,System.Diagnostics.Stopwatch timer){var before=timer.Elapsed.TotalMilliseconds;var absoluteStartedMs=System.Diagnostics.Stopwatch.GetTimestamp()*1000.0/System.Diagnostics.Stopwatch.Frequency;var shot=ScreenPixels();var elapsed=timer.Elapsed.TotalMilliseconds;var image=$"motion-{theme}-{label}-{phase}-{requested}";await SaveEffectImage(image,shot.Pixels,shot.Width,shot.Height);motionRows.Add(new{name=$"{theme}-{label}",kind,theme,phase,requestedMs=requested,elapsedMs=elapsed,captureStartedMs=before,absoluteStartedMs,image=image+".png",props,bounds=Rect(control),popupCount=VisualTreeHelper.GetOpenPopupsForXamlRoot(root.XamlRoot).Count,shot.Foreground,shot.CaptureMode});}
    await Capture("Before",0,System.Diagnostics.Stopwatch.StartNew());
    foreach(var phase in new[]{"Open","Close"}){var timer=System.Diagnostics.Stopwatch.StartNew();if(phase=="Open")show();else hide();foreach(var time in new[]{0,16,33,67,100,167,250,350,500,750,900}){var delay=time-timer.Elapsed.TotalMilliseconds;if(delay>0)await Task.Delay((int)Math.Ceiling(delay));await Capture(phase,time,timer);}}
   }
   foreach(var label in new[]{"NumberBox","AutoSuggestBox","ComboBox","ComboBoxEditable","ComboBoxSelect","ComboBoxEditableSelect","ContentDialog","TeachingTip"}){
