    else if(label=="ContentDialog"){var b=new ContentDialog{XamlRoot=root.XamlRoot,RequestedTheme=root.RequestedTheme,Title="Save your work?",Content=new TextBlock{Text="Your changes will be saved to the cloud.",TextWrapping=TextWrapping.Wrap},PrimaryButtonText="Save",CloseButtonText="Cancel",DefaultButton=ContentDialogButton.Primary};await Motion(label,label,b,()=>{_=b.ShowAsync();},()=>b.Hide(),new{title="Save your work?",primaryButtonText="Save",closeButtonText="Cancel",defaultButton="Primary"});}
