public sealed partial class ProbeApplication{
 async Task RunComposedFormatting(){try{
  root.Children.Clear();var b=new NumberBox{Width=240,SpinButtonPlacementMode=NumberBoxSpinButtonPlacementMode.Inline};root.Children.Add(b);root.UpdateLayout();await Task.Delay(80);var values=new List<object>();var inputs=new List<object>();
  foreach(var value in new[]{0.30000000000000004,1.234567890123,1.2345678905,-1.2345678905,1.000000000001,9999999999.9,1e-9,1e9,1e100,double.MaxValue}){b.Value=value;root.UpdateLayout();values.Add(new{value,text=b.Text});}
  foreach(var expression in new[]{false,true})foreach(var text in new[]{"2 + 3 * 4","1e3","1,234.5",".5","1/0","bad","","1.234567890123"}){b.AcceptsExpression=expression;b.Value=42;b.Text=text;root.UpdateLayout();inputs.Add(new{text,expression,value=double.IsFinite(b.Value)?(double?)b.Value:null,display=b.Text});}
  var increments=new List<object>();b.NumberFormatter=new Windows.Globalization.NumberFormatting.DecimalFormatter{IntegerDigits=1,FractionDigits=2,NumberRounder=new Windows.Globalization.NumberFormatting.IncrementNumberRounder{Increment=.25,RoundingAlgorithm=Windows.Globalization.NumberFormatting.RoundingAlgorithm.RoundHalfUp}};
  foreach(var value in new[]{2.36,2.375,-2.375,2.1}){b.Value=value;root.UpdateLayout();increments.Add(new{value,text=b.Text});}
  File.WriteAllText(Path.Combine(Program.Output,"composed-number-format.json"),JsonSerializer.Serialize(new{values,inputs,increments,formatter=b.NumberFormatter.GetType().FullName,scope="same-SDK public Value/Text setters; invariant probe locale inherited from Windows"},EffectsJson));File.WriteAllText(Path.Combine(Program.Output,"composed-controls-complete.json"),"{}");
 }catch(Exception e){File.WriteAllText(Path.Combine(Program.Output,"composed-controls-error.txt"),e.ToString());}Exit();}
